//---------------------------------------------------
// Sous programme Sys_Init
// Auteur: Rolle Clement
// Desc.: sous programme d'initialisation du systeme
// Ver. Date: V00 20250519 Cr�ation (YYYYMMDD)	
//---------------------------------------------------

void Sys_Init(void)
{
    // Oscillator 32MHz  

    // 111 EXTOSC(1)
    // 110 HFINTOSC (1-32 MHz)(2)
    // 101 LFINTOSC
    // 100 SOSC
    // 011 Reserved
    // 010 EXTOSC with 4x PLL(1)
    // 001 HFINTOSC with 2x PLL (32 MHz)(1)
    // 000 Reserved
    OSCCON1bits.NOSC = 0b110;

    // HFFRQ<2:0>: HFINTOSC Frequency Selection bits
    // Nominal Freq (MHz):
    // 111 = Reserved
    // 110 = 32
    // 101 = 16
    // 100 = 12
    // 011 = 8
    // 010 = 4
    // 001 = 2
    // 000 = 1
    OSCFRQbits.HFFRQ = 0b110;

    // NDIV<3:0>/
    // CDIV<3:0> Clock divider
    // 1111-1010 Reserved    
    // 1001 512
    // 1000 256
    // 0111 128
    // 0110 64
    // 0101 32
    // 0100 16
    // 0011 8
    // 0010 4
    // 0001 2
    // 0000 1
    OSCCON1bits.NDIV = 0b0000;

    // Pins
    ANSELA = 0; // mode digital PORTA
    ANSELB = 0; // mode digital PORTB
    ANSELC = 0; // mode digital PORTC

    LATA = 0b10000000; // RA0->D3 RA1->D2 RA2->D1 RA3->D0 RA4->E RA5->R/W RA6->RS RA7->BL_CTRL_N (actif bas)
    LATB = 0b00000000; // RB0->Tx2 RB1->Rx2 RB2..3->NC->'0' RB4..5->RELAIS_CTRL
    LATC = 0b00000000; // RC0..RC2 switch actif bas RC3->SCL RC4->SDA RC5->WP RC6->Rx1 RC7->Tx1 (erreur hardware inversion Tx1 et Rx1)

    TRISA = 0b00000000; // Tout en sortie
    TRISB = 0b00000010; // Tout en sortie sauf Rx2 (RB1)
    TRISC = 0b01011111; // Tout en sortie sauf pour les switch, l'I2C et Rx1 (RC0..RC4 RC6) (erreur hardware Rx->RC6 au lieu de RC7, invertion Tx1 et Rx1)

    WPUA = 0b00000000; // pas de pull up internes
    WPUB = 0b00000000; // pas de pull up internes
    WPUC = 0b00000111; // pull up internes sur les boutons poussoirs (RC0..2)

    // UART PPS
    RX1DTPPS = 0x16; // RC6->EUSART1:Rx1   
    RC7PPS = 0x0F; // RC7->EUSART1:Tx1   
    RB0PPS = 0x11; // RB0->EUSART2:Tx2
    RX2DTPPS = 0x09; // RB1->EUSART2:Rx2 

    // I2C PPS
    SSP1CLKPPS = 0x13; //RC3->MSSP1:SCL1;
    RC3PPS = 0x15; //RC3->MSSP1:SCL1;
    SSP1DATPPS = 0x14; //RC4->MSSP1:SDA1;
    RC4PPS = 0x16; //RC4->MSSP1:SDA1;

    // LCD
    LCD_Init();

    // USART
    Uart1Init_DTE();
    Uart2Init_modem();

    // Interruptions (MCC)
    INTERRUPT_Initialize();


}
